var items = $input.all();
for (var i = 0; i < items.length; i++) {
  var fullJson = items[i].json;

  function findEmail(obj) {
    if (!obj || typeof obj !== 'object') return '';
    var keys = Object.keys(obj);
    for (var k = 0; k < keys.length; k++) {
      var key = keys[k]; var val = obj[key];
      if (typeof val === 'string' && val.indexOf('@') !== -1) {
        if (key.toLowerCase().indexOf('mail') !== -1 || key.toLowerCase().indexOf('email') !== -1)
          return val.trim().toLowerCase();
      }
      if (typeof val === 'object' && val !== null) {
        var found = findEmail(val); if (found) return found;
      }
    }
    return '';
  }

  function findName(obj) {
    if (!obj || typeof obj !== 'object') return '';
    var nameKeys = ['name','nombre','lead_name','nombre_persona','nombre_y_apellidos','full_name'];
    var keys = Object.keys(obj);
    for (var k = 0; k < keys.length; k++) {
      var kl = keys[k].toLowerCase();
      if (nameKeys.indexOf(kl) !== -1 || kl.indexOf('nombre') !== -1 || kl === 'name') {
        if (typeof obj[keys[k]] === 'string' && obj[keys[k]].trim().length >= 2)
          return obj[keys[k]].trim();
      }
    }
    return '';
  }

  function findField(obj, fieldNames) {
    if (!obj || typeof obj !== 'object') return '';
    var keys = Object.keys(obj);
    for (var k = 0; k < keys.length; k++) {
      var kl = keys[k].toLowerCase().replace(/[_\-\s]/g, '');
      for (var f = 0; f < fieldNames.length; f++) {
        if (kl === fieldNames[f].toLowerCase().replace(/[_\-\s]/g, ''))
          return (obj[keys[k]] || '').toString().trim();
      }
    }
    return '';
  }

  var email = findEmail(fullJson);
  var name  = findName(fullJson);

  if (!email || email.indexOf('@') === -1) {
    items[i].json = { valid: false, error: 'Email no encontrado.' };
    return items;
  }

  var source_page = 'contacto';
  var allStr = JSON.stringify(fullJson).toLowerCase();
  if (allStr.indexOf('sector') !== -1) source_page = 'blueprint';
  if (allStr.indexOf('negocio') !== -1) source_page = 'auditoria';

  items[i].json = {
    valid: true,
    raw_email:   email,
    raw_name:    name,
    raw_phone:   findField(fullJson, ['phone','telefono','whatsapp','tel','movil']) || 'N/A',
    raw_company: findField(fullJson, ['company','company_name','empresa','nombre_negocio','empresa_organizacion']) || 'No especificada',
    raw_message: findField(fullJson, ['message','mensaje','proyecto','necesidad','problema_principal','descripcion']) || 'Sin mensaje',
    raw_service: findField(fullJson, ['service','servicio','prioridad_mejora','prioridad','interes']) || 'Consultoria General',
    raw_budget:  findField(fullJson, ['budget','presupuesto','presupuesto_mensual']) || 'No especificado',
    raw_website: findField(fullJson, ['website','web','url','sitio_web']) || '',
    raw_sector:  findField(fullJson, ['sector','sector_operativo','industria']) || 'General',
    raw_source:  findField(fullJson, ['source','utm_source','origen']) || 'web',
    raw_source_page: source_page
  };
}
return items;

var items = $input.all(); var item = items[0].json;
var prompt = `DIAGNÓSTICO TÉCNICO INDUSTRIAL - ZYNDRIX 2026

### DATOS DEL LEAD
- **Entidad:** ${item.company}
- **Sector:** ${item.sector}
- **Necesidad:** ${item.message}

### INSTRUCCIONES DE FORMATO
Genera un BLUEPRINT INDUSTRIAL. No uses párrafos largos. Usa ÚNICAMENTE:
1. **Secciones con Título en negrita**
2. **Listas con iconos industriales** (⚙️, 🧠, ⚡)
3. **Roadmap de 14 días** en pasos numerados con bolding.

TU TAREA: Analizar la DEUDA OPERATIVA y proponer una arquitectura de 3 capas. Sé agresivo y profesional.

Responde siempre con este JSON:
{"tier":"VIP|ALTO|MEDIO|BAJO","score":0-100,"reasoning":"CONTENIDO ESTRUCTURADO CON MARKDOWN E ICONOS AQUÍ","priority_action":"ACCIÓN INMEDIATA","estimated_value":"EUR"}`;
items[0].json.aiBody = JSON.stringify({ model: "gpt-4o", temperature: 0.15, messages: [{role: "system", content: "Eres el Chief Architect de Zyndrix IA."}, {role: "user", content: prompt}] });
return items;

var items = $input.all(); var lead = $('Normalize Data').first().json; var aiRaw = '';
try { aiRaw = items[0].json.choices[0].message.content || '{}'; } catch(e) { aiRaw = '{}'; }

function fixUtf8(str) {
  if (!str) return str;
  try {
    var fixed = Buffer.from(str, 'latin1').toString('utf8');
    return (fixed.indexOf('\uFFFD') === -1) ? fixed : str;
  } catch(e) { return str; }
}

var parsed = {};
try {
  var cleaned = aiRaw.replace(/^```(?:json)?\n?/, '').replace(/\n?```$/, '').trim();
  parsed = JSON.parse(cleaned);
} catch(e) {
  parsed = {tier:'MEDIO',score:50,reasoning:'Error IA',priority_action:'Contactar',estimated_value:'Consultar'};
}

return [{json:{
  ...lead,
  tier:parsed.tier, score:parsed.score,
  reasoning:       fixUtf8(parsed.reasoning || ''),
  priority_action: fixUtf8(parsed.priority_action || 'Contactar'),
  estimated_value: fixUtf8(parsed.estimated_value || 'Consultar')
}}];

